// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address attackerAddr) public {
        vm.assume(attackerAddr != address(0));
        vm.assume(attackerAddr != address(this));

        Attacker attacker = new Attacker(address(c));

        address initialOwner = c.owner();
        vm.assume(address(attacker) != initialOwner);

        bool ok;
        try attacker.doCallOwned() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}

contract Attacker {
    Owned immutable target;
    constructor(address _target) { target = Owned(_target); }
    function doCallOwned() external {
        target.owned();
    }
}
